class Solution {
  private static final long M1 = 1_000_000_007L, M2 = 998_244_353L, B1 = 100_003L, B2 = 100_019L;

  public int longestCommonSubpath(int n, int[][] paths) {
    int lo = 0, hi = Integer.MAX_VALUE;
    for (int[] p : paths) hi = Math.min(hi, p.length);
    while (lo < hi) {
      int mid = (lo + hi + 1) >>> 1;
      if (common(paths, mid)) lo = mid;
      else hi = mid - 1;
    }
    return lo;
  }

  // is there a subpath of length len present in every path?
  private boolean common(int[][] paths, int len) {
    Set<Long> shared = null;
    long p1 = 1, p2 = 1;
    for (int i = 1; i < len; i++) {
      p1 = p1 * B1 % M1;
      p2 = p2 * B2 % M2;
    }
    for (int[] path : paths) {
      Set<Long> hashes = new HashSet<>();
      long h1 = 0, h2 = 0;
      for (int i = 0; i < path.length; i++) {
        if (i >= len) {
          h1 = ((h1 - (path[i - len] + 1) * p1) % M1 + M1) % M1;
          h2 = ((h2 - (path[i - len] + 1) * p2) % M2 + M2) % M2;
        }
        h1 = (h1 * B1 + path[i] + 1) % M1;
        h2 = (h2 * B2 + path[i] + 1) % M2;
        if (i >= len - 1) hashes.add(h1 << 32 | h2);
      }
      if (shared == null) shared = hashes;
      else shared.retainAll(hashes);
      if (shared.isEmpty()) return false;
    }
    return true;
  }
}
